static const float bias2[4] = {0.0445918851f, -0.0454946868f, 0.0196240488f, 0.0318047926f};

void policyForward(const float obs[POLICY_OBS_DIM], float actionOut[POLICY_ACTION_DIM])
{
  float h0[128];
  for (int j = 0; j < 128; j++) {
    float acc = bias0[j];
    for (int k = 0; k < 21; k++) {
      acc += obs[k] * kernel0[k][j];
    }
    h0[j] = tanhf(acc);
  }
  float h1[128];
  for (int j = 0; j < 128; j++) {
    float acc = bias1[j];
    for (int k = 0; k < 128; k++) {
      acc += h0[k] * kernel1[k][j];
    }
    h1[j] = tanhf(acc);
  }
  for (int j = 0; j < 4; j++) {
    float acc = bias2[j];
    for (int k = 0; k < 128; k++) {
      acc += h1[k] * kernel2[k][j];
    }
    actionOut[j] = acc;
  }
}
